def comps(g, bg):
    seen=set(); out=[]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j]!=bg and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); c=[]
                while st:
                    x,y=st.pop(); c.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<len(g) and 0<=ny<len(g[0]) and g[nx][ny]!=bg and (nx,ny) not in seen:
                            seen.add((nx,ny)); st.append((nx,ny))
                out.append(c)
    return out
